const salePaid = (sale) => Number(sale?.paidAmount ?? sale?.total ?? 0);
const saleBalance = (sale) => Math.max(0, Number(sale?.balance ?? (Number(sale?.total||0) - salePaid(sale))));
const salePaymentStatus = (sale) => saleBalance(sale) <= 0 ? 'Pagado' : (salePaid(sale) > 0 ? 'Abonado' : 'Pendiente');
const paymentBelongsTo = (payment,sourceId,sourceType='') => payment?.sourceId===sourceId || payment?.saleId===sourceId || payment?.orderId===sourceId || payment?.accountId===sourceId || payment?.accountId===`${sourceType}:${sourceId}`;
const initialPaymentTotal = (record={},type='sale') => { const lines=normalizePaymentBreakdown(record,type); return lines.reduce((a,x)=>a+Number(x.amountUsd??x.amount??0),0); };
const normalizeKey = (value='') => String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
