const normalizePaymentBreakdown = (record={},type='sale') => {
  if(Array.isArray(record.paymentBreakdown)&&record.paymentBreakdown.length) return record.paymentBreakdown.map(x=>({...x,id:x.id||uid(),amount:Number(x.amount||0),amountUsd:Number(x.amountUsd??x.amount??0)}));
  const paid=type==='order'?Number(record.deposit||0):salePaid(record);
  return paid>0?[paymentLine(type==='order'?(record.paymentMethod||'Efectivo'):(record.payment||'Efectivo'),paid,type==='order'?(record.depositReference||''):(record.reference||''),'USD',record.exchangeRate||0)]:[];
};
const nextVisibleCode = (rows=[],prefix='V') => `${prefix}-${String(Math.max(0,...rows.map(x=>Number(String(x.number||'').match(/(\d+)$/)?.[1]||0)))+1).padStart(4,'0')}`;
