function Login({settings={}}){
  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [mode,setMode]=useState('login');
  const [loading,setLoading]=useState(false);
  const submit = async () => {
    if(!email || !password) return alert('Correo y contrasena son obligatorios');
    setLoading(true);
    const result = mode === 'login'
      ? await supabase.auth.signInWithPassword({ email, password })
      : await supabase.auth.signUp({ email, password });
    setLoading(false);
    if(result.error) return alert(result.error.message);
    if(mode === 'signup') alert('Usuario creado. Si Supabase pide confirmacion, revisa el correo antes de entrar.');
  };
  return <div className="loginPage loginV2">
    <div className="loginAurora auroraA"></div><div className="loginAurora auroraB"></div>
    <div className="opticalOrb orbA"></div><div className="opticalOrb orbB"></div><div className="opticalBridge"></div>
    <main className="loginV2Shell">
      <section className="loginHeroPanel">
        <div className="heroBrand">{settings.logo ? <img className="heroLogo" src={settings.logo} alt="Logo GafasCity"/> : <div className="heroLogoFallback">GC</div>}<div><span>GAFASCITY</span><small>Sistema de gestion optica</small></div></div>
        <div className="heroCopy"><span className="heroPill">OPERACION INTELIGENTE</span><h2>Todo el control de la optica en un solo lugar.</h2><p>Ventas, inventario, formulas, ordenes y laboratorios conectados en una experiencia clara y segura.</p><div className="heroFeatures"><span>Acceso por empleado</span><span>Informacion sincronizada</span><span>Seguimiento en tiempo real</span></div></div>
        <div className="heroFoot">GafasCity ERP <span>.</span> Produccion 3.2</div>
      </section>
      <section className="loginFormPanel">
        <div className="mobileLoginLogo">{settings.logo ? <img src={settings.logo} alt="Logo GafasCity"/> : <span>GC</span>}</div>
        <div className="loginFormHead"><span className="loginMiniLabel">ACCESO SEGURO</span><h1>{mode === 'login' ? 'Iniciar sesion' : 'Crear usuario'}</h1><p>{mode === 'login'?'Ingresa tus datos para continuar al sistema.':'Crea una cuenta autorizada para ingresar.'}</p></div>
        <div className="loginFormBody"><label className="loginV2Field"><span>Correo electronico</span><div><span className="inputGlyph">@</span><input value={email} placeholder="usuario@gafascity.com" onChange={e=>setEmail(e.target.value)}/></div></label><label className="loginV2Field"><span>Contrasena</span><div><span className="inputGlyph">*</span><input value={password} placeholder="Escribe tu contrasena" type="password" onChange={e=>setPassword(e.target.value)}/></div></label><button className="loginV2Primary" onClick={submit} disabled={loading}>{loading ? 'Procesando...' : (mode === 'login' ? 'Entrar a GafasCity' : 'Crear usuario')}</button><button className="loginV2Link" onClick={()=>setMode(mode === 'login' ? 'signup' : 'login')}>{mode === 'login' ? 'Necesitas crear un usuario?' : 'Volver a iniciar sesion'}</button></div>
        <div className="loginSecurity">Conexion protegida y acceso autorizado</div>
      </section>
    </main>
  </div>
}
