function MixedPaymentEditor({lines,onChange,targetUsd=0,targetBs=0}){
  const safe=Array.isArray(lines)&&lines.length?lines:[paymentLine('Efectivo',0,'','USD')];
  const setLine=(id,patch)=>onChange(safe.map(x=>x.id===id?{...x,...patch}:x));
  const totalUsd=safe.filter(x=>x.currency!=='BS').reduce((sum,x)=>sum+Number(x.amount||0),0);
  const totalBs=safe.filter(x=>x.currency==='BS').reduce((sum,x)=>sum+Number(x.amount||0),0);
  const diffUsd=Number(targetUsd||0)-totalUsd,diffBs=Number(targetBs||0)-totalBs;
  return <div className="mixedPaymentBox"><div className="paymentLines">{safe.map((line,index)=><div className="paymentLineCard" key={line.id}><b>Pago {index+1}</b><Select p="Método" v={line.method} on={v=>setLine(line.id,{method:v})} opts={paymentOptions.filter(x=>x!=='Mixto').map(x=>[x,x])}/><Select p="Moneda" v={line.currency||'USD'} on={v=>setLine(line.id,{currency:v,amount:''})} opts={[["USD","USD"],["BS","Bolívares"]]}/><Input p={`Monto ${line.currency==='BS'?'Bs.':'USD'}`} type="number" v={line.amount} on={v=>setLine(line.id,{amount:v})}/><Input p="Referencia" v={line.reference||''} on={v=>setLine(line.id,{reference:v})}/>{safe.length>1&&<button type="button" className="mini danger" onClick={()=>onChange(safe.filter(x=>x.id!==line.id))}>Eliminar</button>}</div>)}</div><button type="button" className="secondary addPaymentButton" onClick={()=>onChange([...safe,paymentLine('Efectivo',0,'','USD')])}>+ Agregar otro método</button><div className="paymentTotals dualCurrencyTotals"><div className="totalBox">Distribuido USD<b>{money(totalUsd)}</b></div><div className="totalBox">Distribuido Bs.<b>{bs(totalBs)}</b></div><div className={`totalBox ${Math.abs(diffUsd)<=.01?'paymentOk':'paymentPending'}`}>Diferencia USD<b>{money(diffUsd)}</b></div><div className={`totalBox ${Math.abs(diffBs)<=.01?'paymentOk':'paymentPending'}`}>Diferencia Bs.<b>{bs(diffBs)}</b></div></div></div>;
}
